CREATE TABLE admins (email TEXT PRIMARY KEY, pass_hash TEXT NOT NULL, salt TEXT NOT NULL, iters INTEGER NOT NULL, created_at TEXT NOT NULL DEFAULT (datetime('now')), last_login TEXT);
CREATE TABLE sessions (token_hash TEXT PRIMARY KEY, email TEXT NOT NULL, expires_at INTEGER NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE login_attempts (id INTEGER PRIMARY KEY AUTOINCREMENT, k TEXT NOT NULL, at INTEGER NOT NULL);
CREATE INDEX idx_attempts ON login_attempts(k, at);
CREATE TABLE cuts (id TEXT PRIMARY KEY, name_hr TEXT NOT NULL, name_en TEXT NOT NULL, sub_hr TEXT DEFAULT '', sub_en TEXT DEFAULT '', desc_hr TEXT DEFAULT '', desc_en TEXT DEFAULT '', kg REAL NOT NULL, start_date TEXT NOT NULL, target INTEGER NOT NULL, eur REAL NOT NULL, active INTEGER NOT NULL DEFAULT 1, sort INTEGER NOT NULL DEFAULT 0, reserved_enquiry INTEGER, updated_at TEXT DEFAULT (datetime('now')));
CREATE TABLE products (id TEXT PRIMARY KEY, cat TEXT NOT NULL, unit TEXT NOT NULL, name_hr TEXT NOT NULL, name_en TEXT NOT NULL, desc_hr TEXT DEFAULT '', desc_en TEXT DEFAULT '', eur REAL NOT NULL, active INTEGER NOT NULL DEFAULT 1, sort INTEGER NOT NULL DEFAULT 0, updated_at TEXT DEFAULT (datetime('now')));
CREATE TABLE workshops (id TEXT PRIMARY KEY, date TEXT NOT NULL, when_hr TEXT DEFAULT '', when_en TEXT DEFAULT '', title_hr TEXT NOT NULL, title_en TEXT NOT NULL, desc_hr TEXT DEFAULT '', desc_en TEXT DEFAULT '', eur REAL NOT NULL, seats INTEGER NOT NULL, active INTEGER NOT NULL DEFAULT 1, sort INTEGER NOT NULL DEFAULT 0);
CREATE TABLE enquiries (id INTEGER PRIMARY KEY AUTOINCREMENT, created_at TEXT NOT NULL DEFAULT (datetime('now')), source TEXT NOT NULL, lang TEXT, name TEXT, phone TEXT, email TEXT, pickup TEXT, note TEXT, items_json TEXT, total_eur REAL, extra_json TEXT, status TEXT NOT NULL DEFAULT 'novo', admin_note TEXT DEFAULT '', ip_hash TEXT);
